/*
 * This file is part of mod-aware-bots-548 (GPL-2.0-or-later, see LICENSE).
 *
 * The price table of the bots' auction house (design decision 0034): one price range per tradable item, read once at start from
 * the world database table playerbots_item_price (data/sql/db-world, generated by tools/economy/export_price_table.py)
 * into memory. The rules that use the ranges are in Utils/PricePolicy.h. Nothing is loaded while
 * AiPlayerbot.Auction.Enable is 0.
 */

#ifndef _PLAYERBOT_PRICETABLE_H
#define _PLAYERBOT_PRICETABLE_H

#include "Define.h"
#include "PricePolicy.h"

namespace PriceTable
{
    // World thread, once from the module's OnStartup. Does nothing while AiPlayerbot.Auction.Enable is 0. Returns the
    // rows kept; 0 (with a log line) when the table is missing or holds no usable row, and the auction house then trades
    // nothing. Rows with an unusable range are dropped and counted in the log.
    uint32 Load();

    // false means "do not trade this item": the table is not loaded, the item is not in it, or its range is unusable.
    // Read-only after Load, so any thread may call it.
    bool Find(uint32 itemEntry, PricePolicy::PriceRange& out);

    uint32 Size();
}

#endif
